export const SCHOOLS: School[] = [
  { name: "ABC Pathways International Kindergarten", slug: "abc-pathways-international-kindergarten", curricula: ["British"], budget: "under400k", website: "https://www.abcpathways.co.th", description: "A British-curriculum kindergarten following the Cambridge framework, part of Bangkok's network of early years international schools.", languageOfInstruction: "English", photo: "/images/schools/abc-pathways-international-kindergarten.jpg" },
  { name: "Anglo Singapore International School", slug: "anglo-singapore-international-school", curricula: ["British", "Singaporean"], budget: "over400k", website: "https://anglosingapore.ac.th", founded: 2003, description: "Founded in 2003 by Julie Sutanto with four students on a single campus, Anglo Singapore has grown to three campuses across Bangkok and Nakhon Ratchasima, combining Cambridge IGCSE with the Singapore curriculum framework and offering High School Diploma, BTEC, and A-Level pathways.", languageOfInstruction: "English", feeRange: "385,800 to 798,800 THB/year", photo: "/images/schools/anglo-singapore-international-school.jpg" },
  { name: "Annabel's Early Years International School", slug: "annabels-early-years-international-school", curricula: ["British"], budget: "under400k", website: "https://www.annabels.ac.th", description: "A British-curriculum early years school in Bangkok, focused specifically on the youngest learners before they move on to primary school elsewhere.", languageOfInstruction: "English", photo: "/images/schools/annabels-early-years-international-school.jpg" },
  { name: "Ascot International School", slug: "ascot-international-school", curricula: ["British", "International Baccalaureate"], budget: "over400k", website: "https://ascot.ac.th", founded: 1995, description: "Ascot is one of the few schools in Bangkok authorized to teach the complete IB continuum: the Primary Years, Middle Years, and Diploma Programmes, plus the Career-related Programme as an additional pathway in the final years for students who want a more vocationally oriented route alongside or instead of the standard Diploma.\n\nFounded in 1995 as Park Place International School before rebranding, Ascot has three decades of local history under its current and former names, giving it a longer track record than many of Bangkok's newer IB-focused schools.\n\nThe school has built a specific niche around football, running an integrated football academy in partnership with coaches from the Thai Premier League, which goes well beyond a typical school PE program and gives serious young players structured, higher level coaching as part of their regular school experience.\n\nFamilies choosing Ascot over NIST or KIS for the full IB continuum are often weighing its specific combination of the Career-related Programme option and football academy partnership against those other schools' different strengths and campus locations.", ageRange: "Ages 2 to 18", languageOfInstruction: "English", feeRange: "331,908 to 594,969 THB/year", photo: "/images/schools/ascot-international-school.jpg" },
  { name: "Associe International Kindergarten Bangkok", slug: "associe-international-kindergarten-bangkok", curricula: ["American", "Japanese", "Thai"], budget: "under400k", website: "https://www.aikb35.ac.th", description: "A kindergarten offering American, Japanese, and Thai curriculum elements side by side, reflecting Bangkok's multicultural family base.", languageOfInstruction: "English, Japanese, Thai", feeRange: "235,200 to 312,000 THB/year", photo: "/images/schools/associe-international-kindergarten-bangkok.jpg" },
  { name: "Bangkok Christian International School", slug: "bangkok-christian-international-school", curricula: ["American", "Christian"], budget: "under400k", website: "https://www.bcis.ac.th", founded: 1997, description: "BCIS was founded in 1997 by the Korean Missionary Fellowship in Thailand, and follows an American curriculum leading to a US high school diploma, with AP courses available in the upper grades for students pursuing university admission in the US or elsewhere.\n\nThe school is grounded in Christian values, including weekly chapel as part of the regular school schedule, though it explicitly welcomes students of all faiths rather than restricting admission to Christian families, which is a meaningful distinction from schools that require religious affiliation.\n\nGiven its founding through a Korean missionary organization, BCIS has historically drawn a notable portion of its community from Bangkok's Korean expatriate population, alongside the broader international and Thai families the school serves more generally.\n\nFamilies weighing BCIS against Bangkok's other Christian American schools like ICS or Ekamai are typically considering similar things: the specific denominational or organizational background behind each school, campus location, and the balance each strikes between academic and faith components.", ageRange: "Kindergarten to Grade 12", languageOfInstruction: "English" },
  { name: "Bangkok Grace International School (BGIS)", slug: "bangkok-grace-international-school-bgis", curricula: ["American", "Christian"], budget: "under400k", website: "https://www.grace.ac.th", founded: 1999, description: "Founded in September 1999 by Rev. Sila Jung, founder of the Thailand Sunday School Institute, BGIS began with five kindergarten students and expanded to Grades 1 through 6 by 2003. It remains a Christ-centered school built around the belief that education should ultimately glorify God.", languageOfInstruction: "English" },
  { name: "Bangkok Patana School", slug: "bangkok-patana-school", curricula: ["British", "International Baccalaureate"], budget: "over400k", description: "Bangkok Patana is a not-for-profit school run under parent governance rather than private ownership, which shapes a lot of how it operates day to day. Fees go back into the school itself rather than to shareholders, and parents sit on the governing council that oversees major decisions, giving families a genuine stake in how the school is run.\n\nAcademically, Patana follows the English National Curriculum from the early years through to IGCSE, then offers the IB Diploma Programme in the final two years rather than A-Levels, which is a deliberate choice that gives graduates a globally recognized qualification suited to university applications outside the UK as well as within it. With around 2,300 students across roughly 70 nationalities, it is by a wide margin the largest British school in Thailand.\n\nThe campus itself sits on close to 40 acres in the Bang Na area, large enough to house separate primary and secondary sections, extensive sports facilities, and purpose built performing arts and science spaces. That scale supports a wide co-curricular program, from competitive sports through IASAS to music, drama, and Duke of Edinburgh Award participation.\n\nFounded in 1957 in the garden playhouse of Rosamund Stuetzel with just 28 students, Patana has grown into one of the reference points for British international education in Southeast Asia, and its graduates regularly go on to Oxford, Cambridge, and Ivy League universities.", website: "https://www.patana.ac.th", founded: 1957, ageRange: "Ages 2 to 18", languageOfInstruction: "English", feeRange: "545,000 to 1,044,000 THB/year", photo: "/images/schools/bangkok-patana-school.jpg" },
  { name: "Bangkok Prep", slug: "bangkok-prep", curricula: ["British"], budget: "over400k", website: "https://www.bangkokprep.ac.th", founded: 2003, description: "Bangkok Prep positions itself as a genuinely British curriculum school without the boarding tradition or UK institutional lineage that Harrow or Shrewsbury carry, which tends to make it feel a bit more like a straightforward day school in tone. It follows the English National Curriculum through IGCSE and A-Levels, with Cambridge as the examining body.\n\nThe school has built a reputation around sustainability specifically, becoming the first school in Thailand to earn Eco Schools Green Flag status, the highest level of that international environmental education award. That focus shows up in the day to day curriculum, not just as an occasional theme week.\n\nBangkok Prep is a member of FOBISIA, ISAT, and the regional BISAC and TISAC sporting conferences, giving students access to a fairly full slate of interscholastic sports and academic competition against other British curriculum schools in the region.\n\nCompared to the very largest British schools in the city, Bangkok Prep tends to run smaller, which some families specifically look for as a way to get more individual attention without giving up the British curriculum and IGCSE/A-Level exam pathway.", ageRange: "Ages 2 to 18", languageOfInstruction: "English", feeRange: "384,800 to 862,200 THB/year" },
  { name: "Basis International School Bangkok", slug: "basis-international-school-bangkok", curricula: ["American"], budget: "over400k", website: "https://basis.ac.th", founded: 2019, description: "BASIS Bangkok is the 35th school in the BASIS Curriculum network, a US-based charter school system known specifically for its subject-specialist teaching model, where students work with a different expert teacher for each core subject from an early age rather than a single generalist homeroom teacher. It opened in 2019 next to Central Rama 2.\n\nThe subject-specialist structure is the school's defining academic feature and a genuine point of difference from most other schools in Bangkok, since it means even young students are taught math by a math specialist, science by a science specialist, and so on, rather than one teacher covering all core subjects.\n\nBASIS Curriculum schools are generally regarded as academically rigorous and fast paced, and that reputation for a demanding academic environment is part of what specifically draws families to BASIS Bangkok over some of the city's other American curriculum options.\n\nAs a relatively new campus, having opened in 2019, BASIS Bangkok is still building its local track record, but it benefits from being part of a larger established BASIS network with a defined curriculum model already proven across dozens of other campuses.", ageRange: "Nursery to Grade 12", languageOfInstruction: "English" },
  { name: "Berkeley International School Bangkok", slug: "berkeley-international-school-bangkok", curricula: ["American"], budget: "over400k", website: "https://www.berkeley.ac.th", founded: 2010, description: "Berkeley is a newer American curriculum school, founded in 2010 and earning full WASC accreditation in 2014, with its first graduating class walking in 2017. That relatively recent founding means Berkeley has a shorter track record than Bangkok's oldest American schools like ISB, but it has built its reputation quickly around strong facilities investment.\n\nThe school follows a US-style college preparatory curriculum, and its campus includes both 25 and 50 meter swimming pools along with a full-size grass soccer field, a level of dedicated athletics infrastructure that goes beyond what many similarly sized international schools in Bangkok offer.\n\nBerkeley positions itself as an American curriculum option for families who want a genuinely college-preparatory track without the scale of ISB, appealing specifically to those who prefer a somewhat smaller community while still getting a full US-accredited academic program with AP courses available.\n\nAs a WASC-accredited school with a decade and a half of operating history now, Berkeley has moved past being an unproven newcomer, though it remains smaller in scale and shorter in institutional history than Bangkok's oldest American schools.", ageRange: "Pre-K to Grade 12", languageOfInstruction: "English" },
  { name: "BERNIE British International Prep & Early Years", slug: "bernie-british-international-prep-kindergarten-early-years", curricula: ["British"], budget: "under400k", website: "https://www.bernie-bipc.co.th", description: "A British-curriculum prep and early years school in Bangkok, focused on foundational education before children move into primary school.", languageOfInstruction: "English" },
  { name: "Bright Skies International School", slug: "bright-skies-international-school", curricula: ["British"], budget: "under400k", website: "https://brightskiesinternationalschool.com", description: "A British-curriculum school based in the Ekamai area of Bangkok, part of the city's range of smaller, community-focused international schools.", languageOfInstruction: "English" },
  { name: "Brighton College Bangkok", slug: "brighton-college-bangkok", curricula: ["British"], budget: "over400k", website: "https://brightoncollege.ac.th", description: "Brighton College Bangkok is part of the Brighton College international network, tied to the original Brighton College in the UK, and like Harrow and Shrewsbury it uses that affiliation to bring UK pastoral structures, house systems, and curriculum planning directly into its Bangkok campus rather than building an independent brand.\n\nThe school follows the English National Curriculum through IGCSE, and has built a particular reputation for its performing arts and academic offerings, positioning itself among the newer wave of UK-affiliated schools that have opened in Bangkok over the past two decades alongside Shrewsbury, Harrow, and Wellington.\n\nAs one of the newer entrants competing directly with Bangkok's established British schools, Brighton College has leaned on its UK affiliation and modern purpose-built facilities to differentiate itself, rather than relying on decades of local history the way Patana or Traill can.\n\nFamilies choosing between Brighton College and its UK-affiliated peers in Bangkok are generally comparing similar things: curriculum consistency with the home UK school, facilities, and location relative to where they live, since the underlying academic offering across this group of schools is broadly similar.", ageRange: "Ages 2 to 18", languageOfInstruction: "English", feeRange: "590,300 to 1,021,800 THB/year", photo: "/images/schools/brighton-college-bangkok.jpg" },
  { name: "British Columbia International School", slug: "british-columbia-international-school", curricula: ["Canadian"], budget: "unknown", website: "https://www.bcisb.ac.th", founded: 2007, description: "Established in 2007, BCISB is the only school in Thailand offering the British Columbia (Canada) curriculum, leading to a Canadian Dogwood Diploma alongside Thai high school equivalency. The program emphasizes inquiry-based, competency-driven learning over traditional exam-only assessment.", ageRange: "Ages 3 to 18", languageOfInstruction: "English" },
  { name: "Bromsgrove International School Thailand", slug: "bromsgrove-international-school-thailand", curricula: ["British"], budget: "over400k", website: "https://www.bromsgrove.ac.th", founded: 2002, description: "Bromsgrove Thailand is affiliated with Bromsgrove School in the UK, joining the cluster of UK-linked British schools that have opened in Bangkok over the past two decades. It follows the English National Curriculum through IGCSE and A-Levels, with the direct UK affiliation shaping curriculum planning and pastoral structure the way it does at Harrow, Shrewsbury, and the other UK-linked schools in the city.\n\nFounded in 2002, Bromsgrove is one of the more established schools in this UK-affiliated group, giving it a longer local track record than some of the newer entrants like King's College or Wellington. Its fee positioning tends to run somewhat lower than several of its UK-affiliated peers, which is a genuine differentiator for families comparing this specific group of schools.\n\nAs with its UK-linked peers, Bromsgrove brings house system structure and pastoral care modeled on the UK original into its Bangkok campus, alongside the standard IGCSE and A-Level exam pathway that this whole cluster of schools shares.\n\nFamilies weighing Bromsgrove against Harrow, Shrewsbury, or Brighton College are typically comparing similar academic outcomes and UK-linked pastoral models, with fee level, campus location, and the specific culture of each home UK institution being the more meaningful points of difference.", ageRange: "Ages 2 to 18", languageOfInstruction: "English", feeRange: "259,100 to 680,100 THB/year" },
  { name: "Canadian International School of Thailand", slug: "canadian-international-school-of-thailand", curricula: ["Canadian", "International Baccalaureate"], budget: "under400k", website: "https://canadianschool.com", description: "Situated on a riverside campus in the Pinklao area, CIST evolved from the long-running Thewphaingarm School and is authorized for the IB Primary Years and Middle Years Programmes, working toward students earning an Ontario Secondary School Diploma.", languageOfInstruction: "English" },
  { name: "Centurion International School Bangkok", slug: "centurion-international-school-bangkok", curricula: ["British"], budget: "under400k", website: "https://cisb.ac.th", description: "Centurion is a private British curriculum school in the Suan Luang district, primarily serving early years and primary-age students rather than offering a full K-12 pathway. It keeps a deliberately small community, with students from 14 or more nationalities and typical class sizes around 25.\n\nThat combination of a private, small-scale structure and genuine international diversity within a relatively compact student body is part of Centurion's specific positioning within Bangkok's crowded British curriculum market, most of which is dominated by larger schools.\n\nBecause Centurion focuses primarily on early years and primary ages, families typically need to plan for a transition to a different secondary school once their children age out, similar to how Tiny Tots functions at the even younger end of the age range.\n\nFamilies drawn to Centurion are generally prioritizing that small, genuinely international primary-focused environment in the Suan Luang area over the scale and full K-12 continuity that larger British schools elsewhere in the city offer.", languageOfInstruction: "English" },
  { name: "Charter International School", slug: "charter-international-school", curricula: ["British"], budget: "over400k", website: "https://charter.ac.th", description: "Charter International School was founded by the Thienprasiddhi family, who also run the Plengprasiddhi Kindergarten schools in Thailand, giving Charter a connection to an established local education background even as a standalone international school. It follows the English National Curriculum.\n\nOne distinctive detail about Charter is that its building design was modeled directly on the founding family's own home, with the explicit intention of making the campus feel less institutional and more like an extension of home life for younger students specifically.\n\nAs a family-founded and family-run school rather than part of a larger international group or UK-affiliated network, Charter operates with more independence in how it shapes its specific culture and priorities compared to schools tied into networks like Nord Anglia or the various UK boarding school affiliates in Bangkok.\n\nFamilies drawn to Charter are often specifically looking for that family-run, home-like atmosphere rather than the scale and brand recognition of a larger international network school, making it a genuinely different kind of option within Bangkok's British curriculum landscape.", languageOfInstruction: "English" },
  { name: "Concordian International School Bangkok", slug: "concordian-bangkok-concordian-international-school-bangkok", curricula: ["International Baccalaureate"], budget: "over400k", website: "https://www.concordian.ac.th", description: "An IB World School near Bangna–Trad that teaches through English, Mandarin Chinese, and Thai, with instruction split roughly evenly between English and Chinese. Concordian offers the IB continuum from early years through Diploma.", ageRange: "Ages 2 to 18", languageOfInstruction: "English, Chinese, Thai", feeRange: "646,200 to 993,300 THB/year" },
  { name: "Denla British School", slug: "denla-british-school", curricula: ["British"], budget: "over400k", website: "https://www.dbsbangkok.ac.th", description: "Denla British School is part of the wider Denla Schools group, which has operated in Thailand for several decades under the same founding family, giving DBS specifically a level of institutional backing that some standalone British schools in Bangkok do not have. It follows an Enhanced British Curriculum, meaning the core National Curriculum for England framework with additional elements layered on top.\n\nThe campus sits in Pak Kret, Nonthaburi, putting it further from central Bangkok than many of the city's British schools, which suits families already living in the northern suburbs or willing to trade a longer commute for the school's specific program and larger site.\n\nDBS built its identity around three explicit pillars beyond straightforward academics: entrepreneurship, creative thinking, and wellbeing, and these show up as structured parts of the curriculum rather than occasional add-on activities, which is a deliberate point of difference from more traditionally exam-focused British schools in the city.\n\nBeing part of the broader Denla Schools group also means DBS can draw on shared institutional resources and a longer local track record than a newly founded standalone international school would have, even though the international campus itself is a more recent addition to the group.", ageRange: "Ages 2 to 18", languageOfInstruction: "English" },
  { name: "DPREP Bangkok", slug: "dprep-bangkok", curricula: ["International Baccalaureate", "American"], budget: "over400k", website: "https://dprep.ac.th", founded: 2018, description: "Founded in 2018 by Lady Didyasarin Tavedikul, a member of the family behind the American School of Bangkok's Sukhumvit and Green Valley campuses, D-PREP (originally Didyasarin Preparatory International School) is a newer Bang Na-area school combining American curriculum elements with the IB framework.", languageOfInstruction: "English" },
  { name: "Ekamai International School", slug: "ekamai-international-school", curricula: ["American", "Adventist"], budget: "under400k", website: "https://www.eis.ac.th", founded: 1946, description: "EIS is operated by the Seventh-day Adventist Mission in Thailand, tracing its roots to 1946 as a church school on Phyathai Road before relocating to its current site in 1957, giving it one of the longer institutional histories among Bangkok's Christian international schools.\n\nThe school follows a US-based curriculum, and has represented students from over 30 nationalities across its history, a genuinely international mix for a school with such specific denominational roots.\n\nAs a Seventh-day Adventist institution specifically, EIS carries a distinct religious identity from the Catholic, generically Christian, or Korean missionary-founded schools elsewhere in Bangkok's faith-based school landscape, which matters for families specifically seeking or avoiding a particular denominational affiliation.\n\nGiven its nearly 80-year history dating back to 1946, EIS has a longer local track record than most of Bangkok's other Christian international schools, most of which were founded considerably more recently in the 1990s or 2000s.", languageOfInstruction: "English" },
  { name: "Garden International School Bangkok", slug: "garden-international-school-bangkok", curricula: ["British"], budget: "over400k", website: "https://www.gardenbangkok.com", founded: 1999, description: "Garden International School Bangkok is part of the wider Garden International School group, which also operates campuses in Malaysia, giving it a regional network behind a single Bangkok site rather than being a fully independent standalone school. It was founded in 1999 in the Sathon district.\n\nThe school follows the British National Curriculum from Early Years through to Sixth Form, and deliberately keeps its campus relatively small and close-knit compared to Bangkok's larger British schools like Patana or Harrow, which is a specific selling point for families who want a smaller community over scale.\n\nBeing part of a multi-country group gives Garden some shared institutional resources and curriculum consistency with its Malaysian sister campuses, though the Bangkok site operates with its own local admissions, staff, and day to day culture.\n\nFamilies choosing Garden over Bangkok's larger British schools are typically prioritizing a smaller, more personal school environment, accepting a smaller range of facilities and co-curricular options in exchange for that closer knit community feel.", ageRange: "Early Years to Year 13", languageOfInstruction: "English" },
  { name: "Global English School", slug: "global-english-school", curricula: ["Blended Learning"], budget: "under400k", website: "https://www.facebook.com/gesthailand/", founded: 1980, description: "Also known as Satit Christian Wittaya, Global English School has been run by the Ektrakul family since 1980, maintaining a close-knit, faith-based community alongside its academic program and after-school clubs.", languageOfInstruction: "English" },
  { name: "Global Indian International School", slug: "global-indian-international-school", curricula: ["Indian"], budget: "under400k", website: "http://www.gisschool.org", description: "This Bangkok campus is part of the wider Global Indian International School network, located in Pathum Thani rather than central Bangkok, and specifically serves the city's Indian community alongside local and other international families interested in the school's specific curriculum approach.\n\nBeing part of a larger international network gives this campus access to shared curriculum resources and institutional consistency with GIIS campuses in other countries, which matters for families who may relocate between GIIS locations internationally.\n\nThe Pathum Thani location places it outside the central Bangkok cluster of international schools, which suits families already based in that area or specifically seeking out this particular school's program regardless of commute distance.\n\nFamilies choosing GIIS Bangkok are typically doing so specifically because of its connection to India-focused curriculum elements and the wider GIIS network, rather than comparing it directly against Bangkok's British or American mainstream international schools.", languageOfInstruction: "English" },
  { name: "Glory Singapore International School", slug: "glory-singapore-international-school", curricula: ["British", "Singaporean"], budget: "under400k", website: "https://glorysingapore.com", description: "A smaller Bangkok school combining British and Singaporean curriculum elements, with a lower public profile than the city's larger Singapore-curriculum providers like SISB.", languageOfInstruction: "English" },
  { name: "Hampton International School", slug: "hampton-international-school", curricula: ["British"], budget: "over400k", website: "https://hamptonschool.ac.th", founded: 2009, description: "A family-owned early years school with campuses in Chaengwattana and Sathorn, teaching a British curriculum with Reggio Emilia-inspired methods for children aged 18 months to 6 years. Hampton has been recognized by Thailand's Ministry of Social Development and Human Security for early years education quality.", ageRange: "18 months to 6 years", languageOfInstruction: "English" },
  { name: "Harrow International School Bangkok", slug: "harrow-international-school-bangkok", curricula: ["British"], budget: "over400k", description: "Harrow Bangkok is part of the Harrow International network, tied to the original Harrow School in the UK, and it leans into that heritage more visibly than most Bangkok international schools, with a house system, uniforms, and traditions modeled directly on the English boarding school original.\n\nThe school follows the English National Curriculum through IGCSE and A-Levels, and offers boarding as an option alongside day places, which is relatively unusual among Bangkok's international schools and appeals to families who want the option even if they do not use it immediately.\n\nHarrow's campus includes the kind of large-scale sports and performing arts facilities that come with the Harrow brand internationally, and the school competes actively in Bangkok's interscholastic sports conference alongside the city's other major British and American schools.\n\nAs with Shrewsbury, Harrow gives Bangkok families a way to access a genuinely UK-linked educational brand without leaving Thailand, which is part of its specific appeal versus schools that are British in curriculum only rather than in institutional lineage.", website: "https://www.harrowschool.ac.th", founded: 1998, ageRange: "Ages 2 to 18", languageOfInstruction: "English", feeRange: "634,600 to 1,063,000 THB/year" },
  { name: "Heathfield International School", slug: "heathfield-international-school", curricula: ["British"], budget: "over400k", website: "https://heathfield.ac.th", founded: 2007, description: "Heathfield formed in 2007 from the former Lord Shaftesbury International School, in partnership with Heathfield School in Kidderminster, UK, giving it a UK institutional link similar in structure to Harrow or Shrewsbury, though on a considerably smaller scale. It follows the English National Curriculum through IGCSE and A-Levels.\n\nThe school sits in the Saphan Sung area, away from the more concentrated cluster of international schools in central Sukhumvit, and deliberately keeps its community small, positioning itself as a genuinely community-focused option rather than competing on scale with Bangkok's larger British schools.\n\nBecause Heathfield formed out of an existing school's transition rather than opening fresh, it carries some institutional continuity predating its current UK partnership, even though the Heathfield-branded identity itself dates to 2007.\n\nFamilies drawn to Heathfield are generally prioritizing a small, tight-knit school community and a UK curriculum link, similar in spirit to Garden International School, over the scale, facilities, and brand recognition that Bangkok's larger UK-affiliated schools offer.", ageRange: "Nursery to Year 12", languageOfInstruction: "English" },
  { name: "International Community School", slug: "international-community-school", curricula: ["American", "Christian"], budget: "over400k", website: "https://www.ics.ac.th", founded: 1993, description: "ICS was founded in 1993 by a coalition of expatriate families and Christian school networks, opening with 120 students in the Sathorn area before relocating to its current Bang Na site as the school grew. It is explicitly Christ-centered in its mission, with faith woven into daily school life rather than treated as a separate program.\n\nThe school holds both WASC and ACSI accreditation, the latter being specific to Christian schools internationally, which signals a genuine dual commitment to both academic rigor and its faith-based identity rather than treating one as secondary to the other.\n\nICS has also expanded beyond Bangkok, operating a second campus in Udon Thani, which is relatively unusual among the city's international schools and reflects demand for a similar faith-based American curriculum option outside the capital.\n\nFamilies specifically seeking a Christian, American curriculum school in Bangkok, rather than a secular one, tend to compare ICS against Bangkok Christian International and Ekamai, the city's other explicitly faith-based American options.", ageRange: "Ages 4 to 18", languageOfInstruction: "English" },
  { name: "International Montessori Center", slug: "international-montessori-center", curricula: ["British", "Montessori"], budget: "under400k", website: "https://www.imc.ac.th", description: "A British-curriculum school built around Montessori teaching methods, offering child-led learning within a structured academic framework.", languageOfInstruction: "English" },
  { name: "International Pioneers School", slug: "international-pioneers-school", curricula: ["British"], budget: "under400k", website: "https://ips.ac.th", founded: 1998, description: "IPS has operated under the explicit tagline Quality Affordable Education since 1998, positioning itself deliberately as a lower-cost alternative within Bangkok's British curriculum landscape rather than competing on premium facilities or brand name. It follows a British curriculum through IGCSE and A-Levels.\n\nThe school operates across multiple Bangkok campuses, including sites in Krungthonburi and Bangkhae, giving it a wider geographic footprint than most single-site international schools in the city, which is part of how it manages to keep fees more accessible while still offering full IGCSE and A-Level pathways.\n\nThat multi-campus structure means families researching IPS should confirm which specific campus they are looking at, since facilities, exact fees, and even year group availability can vary between sites within the same overall school.\n\nFamilies drawn to IPS are typically prioritizing genuine affordability within a proper British IGCSE and A-Level framework, rather than the premium positioning of schools like Patana or the UK-affiliated boarding schools elsewhere in the city.", languageOfInstruction: "English" },
  { name: "IPC International Kindergarten", slug: "ipc-international-kindergarten", curricula: ["British"], budget: "under400k", website: "https://www.ipcthai.com", founded: 1983, description: "IPC, formally the International Pre-School Centre, was founded in 1983 by Khun Marianne Chirathivat and family, making it one of Bangkok's oldest dedicated preschools, predating most of the city's current wave of international kindergartens by well over a decade.\n\nThe Chirathivat family name carries significant local business recognition in Thailand, and IPC's founding by a member of that family reflects a broader pattern of established Thai families investing early in international-standard early childhood education for the local and expatriate community.\n\nAs a preschool specifically focused on early childhood education for young children, rather than a full K-12 institution, IPC functions as a starting point that families move on from, similar to Tiny Tots, once children reach primary school age.\n\nWith over four decades of operating history, IPC has a longer track record than nearly all of Bangkok's other dedicated international preschools, most of which opened considerably more recently.", languageOfInstruction: "English" },
  { name: "Kevalee International School", slug: "kevalee-international-school", curricula: ["American"], budget: "under400k", website: "https://www.kevalee.ac.th", founded: 1996, description: "Kevalee began in 1996 as a home-based kindergarten run by Mrs. Juliana, an educator who already had more than 40 years of experience at international schools in Bangkok before founding her own. That personal, experience-driven origin sets it apart from schools founded as corporate or institutional ventures from the start.\n\nThe school expanded significantly in 2006, growing from its original kindergarten focus to cover the full range from Grade 1 through Grade 12, moving to a purpose-built campus in the Klong Samwa district to accommodate that growth.\n\nHaving grown organically from a single founder's home-based kindergarten into a full K-12 school over three decades, Kevalee carries a more personal, founder-driven institutional culture than schools that opened at full scale from day one.\n\nFamilies drawn to Kevalee are often specifically interested in that founder-led history and the sense of continuity it brings, alongside the practical benefit of a full K-12 pathway on one campus in the Klong Samwa area.", languageOfInstruction: "English" },
  { name: "KiddyKare International Kindergarten", slug: "kiddykare-international-kindergarten", curricula: ["British"], budget: "under400k", website: "https://www.kiddykare.ac.th", description: "KiddyKare is a British curriculum kindergarten serving families in Bangkok's early years and pre-primary age range, part of the city's long-established network of small international preschools that families use before transitioning to a primary school.\n\nAs a kindergarten-only provider, KiddyKare's core offering is the youngest end of the international school system, and families typically research and select a separate primary school in parallel, since KiddyKare itself does not carry students through to primary or secondary levels.\n\nOperating within Bangkok's crowded early years market means schools like KiddyKare typically differentiate through campus atmosphere, class sizes, and specific pedagogical approach within the shared British curriculum foundation, rather than through exam results or secondary school outcomes, since those come later at a different school entirely.\n\nFamilies researching KiddyKare are generally comparing it against Bangkok's other standalone kindergartens like Tiny Tots, IPC, or The First Steps, weighing location, atmosphere, and specific program details among otherwise broadly similar early years options.", languageOfInstruction: "English" },
  { name: "KIS International School Bangkok", slug: "kis-international-school-bangkok", curricula: ["International Baccalaureate"], budget: "over400k", website: "https://www.kis.ac.th", description: "KIS is one of the smaller full-continuum IB schools in Bangkok, deliberately built around a more intimate community than the city's largest IB providers like NIST. It teaches the Primary Years, Middle Years, and Diploma Programmes as one continuous IB pathway from age 3 through to graduation.\n\nThe campus sits close to the city center near Huai Khwang, which keeps it within easier reach of central Bangkok neighborhoods compared to some of the larger suburban campuses further from downtown. That central location is part of the appeal for families who prioritize commute time.\n\nDespite its smaller size relative to NIST or ISB, KIS has built a strong reputation specifically for its IB Diploma exam results, and the school leans into its smaller scale as a selling point, arguing that a tighter knit community allows for more individual attention across the full IB continuum.\n\nFamilies choosing KIS over Bangkok's larger IB providers are typically prioritizing community size and location over the scale of facilities and co-curricular breadth that a bigger campus like NIST or ISB can offer.", ageRange: "Ages 3 to 19", languageOfInstruction: "English", feeRange: "459,800 to 984,700 THB/year", photo: "/images/schools/kis-international-school-bangkok.jpg" },
  { name: "KPIS International School", slug: "kpis-international-school", curricula: ["American"], budget: "unknown", website: "https://kpis.ac.th", founded: 2005, description: "KPIS is a privately owned, family-established school in the Ramintra area of northern Bangkok, following a US-based curriculum. It has held full WASC accreditation since 2009, giving it a formally recognized US-standard academic program despite being a smaller, independently run school rather than part of a larger international group.\n\nBeing family-owned rather than corporately run or tied to a UK or international school network gives KPIS more independence in shaping its specific culture and priorities, similar in structure to Charter International School, though with an American rather than British curriculum base.\n\nThe Ramintra location places KPIS further from the central Sukhumvit cluster of international schools, which suits families already based in northern Bangkok or those specifically prioritizing that part of the city over a shorter commute to downtown.\n\nFounded in 2005, KPIS has built a two-decade track record as a smaller, independently owned American curriculum option, appealing to families who want WASC-level accreditation without the scale of Bangkok's largest American schools like ISB.", ageRange: "Nursery to Grade 12", languageOfInstruction: "English" },
  { name: "MYIS International School", slug: "magic-years-international-school-thailand", curricula: ["International Baccalaureate", "American"], budget: "over400k", website: "https://magicyears.ac.th", founded: 1990, description: "Founded in 1990 near the Nichada Thani expatriate community in Nonthaburi, MYIS is one of only a handful of Bangkok-area schools offering both the IB Primary Years and Middle Years Programmes, with plans to add the Diploma Programme by 2027. The small, family-centered campus includes a saltwater pool, science labs, and a small farm.", ageRange: "Ages 1 to 16", languageOfInstruction: "English" },
  { name: "NIST International School Bangkok", slug: "nist-international-school-bangkok", curricula: ["International Baccalaureate"], budget: "over400k", description: "NIST holds a specific distinction among Bangkok's IB schools: it was the first school in Thailand authorized to teach the complete IB continuum, the Primary Years, Middle Years, and Diploma Programmes, as one continuous framework rather than adding the Diploma onto a different curriculum base in the final years. That matters for families who want IB-style inquiry based learning from the very start of a child's education, not just at the end.\n\nThe school was founded in 1992 with backing from Bangkok's United Nations community, and that international, mission-driven origin still shows in its makeup. NIST is run as a not-for-profit under a parent-elected board, and its student body is unusually diverse even by Bangkok international school standards, with no single nationality dominating enrollment.\n\nThe central Sukhumvit campus puts NIST within easy reach of the Sukhumvit corridor neighborhoods where many expat families already live, which is part of why it is a popular choice for families prioritizing a shorter commute over a larger suburban campus. Facilities include dedicated primary and secondary buildings, science and design technology labs, and strong arts and athletics programs.\n\nNIST is consistently regarded as one of the strongest IB Diploma results performers in Bangkok, and it competes in IASAS alongside ISB, Patana, and other top regional schools, giving students a fairly serious level of interscholastic sports and arts competition to take part in.", website: "https://www.nist.ac.th", founded: 1992, ageRange: "Ages 3 to 18", languageOfInstruction: "English", feeRange: "650,200 to 1,132,800 THB/year", photo: "/images/schools/nist-international-school-bangkok.jpg" },
  { name: "The American School of Bangkok (ASB)", slug: "the-american-school-of-bangkok-asb", curricula: ["American", "International Baccalaureate"], budget: "over400k", website: "https://asb.ac.th", founded: 1983, description: "One of Bangkok's longest-running American schools, ASB opened in 1983 and now operates two campuses: the original Sukhumvit site, rebranded XCL American School of Bangkok in 2022 under XCL Education, and the newer Green Valley campus, established in 1997, which offers day and boarding options built around Common Core standards, AP courses, and an IB Diploma pathway.", languageOfInstruction: "English", photo: "/images/schools/the-american-school-of-bangkok-asb.jpg" },
  { name: "The British School of Bangkok (Topsy Turvy)", slug: "the-british-school-of-bangkok-topsy-turvy-international-school", curricula: ["British"], budget: "under400k", website: "https://bsbangkok.ac", description: "A British-curriculum early years and primary school in Bangkok, part of the city's network of smaller National Curriculum for England providers.", languageOfInstruction: "English" },
  { name: "The Country School by ELC", slug: "the-country-school-by-elc", curricula: ["British"], budget: "under400k", website: "https://www.elc.ac.th", description: "Part of the ELC (Early Learning Centre) family of schools in Bangkok, offering a British-curriculum, nature-oriented early education setting.", languageOfInstruction: "English" },
  { name: "The First Steps International School", slug: "the-first-steps-international-school", curricula: ["British"], budget: "under400k", website: "https://thefirststeps.ac.th", description: "The First Steps is a British curriculum early years and pre-school program in Bangkok, part of the city's established network of smaller international kindergartens that serve local and expat families before children move on to a primary school.\n\nAs an early years specialist rather than a full K-12 school, The First Steps functions similarly to KiddyKare, Tiny Tots, and IPC within Bangkok's early education landscape, with families typically planning ahead for which primary school their child will transition to once they age out of the early years program.\n\nWithin this crowded segment of Bangkok's international school market, schools like The First Steps generally differentiate on campus atmosphere, class sizes, and specific teaching approach, since the underlying British early years curriculum framework is broadly shared across this category of school.\n\nFamilies choosing The First Steps are typically weighing it against Bangkok's other standalone early years providers on location, atmosphere, and fit for their specific child, rather than on exam outcomes or secondary pathways, which come later at a different school.", languageOfInstruction: "English" },
  { name: "The Purple Elephant 55", slug: "the-purple-elephant-55", curricula: ["English Program"], budget: "under400k", website: "https://www.elc.ac.th", description: "Part of the ELC family of schools in Bangkok, The Purple Elephant offers an English Program environment for younger learners.", languageOfInstruction: "English" },
  { name: "The Tiny Seeds International Pre-School", slug: "the-tiny-seeds-international-pre-school-bangkok", curricula: ["English Program"], budget: "under400k", website: "https://www.elc.ac.th", description: "Part of the ELC family of schools in Bangkok, The Tiny Seeds offers an English Program pre-school setting for the city's youngest learners.", languageOfInstruction: "English" },
  { name: "The Village International Education Centre (VIE)", slug: "the-village-international-education-centre-vie", curricula: ["British"], budget: "over400k", website: "https://www.village-education.com", description: "A British-curriculum school dedicated specifically to children with special educational needs, with over 16 years of experience. VIE's staff includes speech, language, and occupational therapists alongside academic teachers, and every student has an Individual Educational Plan built around their specific needs.", languageOfInstruction: "English" },
  { name: "Thonglor Greenfield Nursery", slug: "thonglor-greenfield-nursery", curricula: ["British"], budget: "under400k", website: "https://www.thonglorgreenfieldnursery.com", description: "A British-curriculum nursery in the Thonglor area of Bangkok, serving families with young children in one of the city's most central expat neighborhoods.", languageOfInstruction: "English" },
  { name: "Tiny Tots International School", slug: "tiny-tots-international-school", curricula: ["British", "Indian"], budget: "under400k", website: "https://tinytotsinternational.com", description: "Tiny Tots is a central Bangkok preschool and kindergarten built around a deliberately cosmopolitan, small-community atmosphere rather than aiming for scale. It serves children from age 1, making it one of the earlier entry-point options among Bangkok's international early years providers.\n\nBeyond its regular weekday program, Tiny Tots also runs a Saturday playgroup, giving families a lower-commitment way to introduce very young children to the school's environment before committing to full-time enrollment, or as a supplementary option for families using a different primary school.\n\nAs a preschool and kindergarten specifically, rather than a K-12 school, Tiny Tots is a starting point that families typically move on from after the early years, making the transition to a primary school elsewhere a normal part of the Tiny Tots experience rather than an exception.\n\nFamilies choosing Tiny Tots are usually prioritizing that specifically cosmopolitan, small-scale early years environment and central Bangkok location for the youngest end of their child's education.", languageOfInstruction: "English" },
  { name: "Traill International School", slug: "traill-international-school", curricula: ["British"], budget: "over400k", website: "https://www.traillschool.ac.th", founded: 1966, description: "Traill holds a specific place in Bangkok's international school history: founded in 1966 by Mr and Mrs Anthony Traill, it was the first British secondary school established in Thailand, opening with just 82 students. Nearly 60 years later, it remains on its original Bang Kapi campus.\n\nThe school follows a British curriculum through IGCSE and A-Levels, and that nearly six-decade history gives it a longer local track record than almost any other British school in the city aside from Bangkok Patana, which was founded around the same era.\n\nDespite that long history, Traill has stayed on its original site rather than expanding into a larger multi-campus operation the way some of the newer UK-affiliated schools have, which keeps it feeling more like a single established community school than a branch of a larger international network.\n\nFamilies drawn to Traill are often specifically interested in that combination of genuine local history and a straightforward, focused British curriculum, rather than the UK institutional branding that Harrow, Shrewsbury, or Wellington bring to their Bangkok campuses.", ageRange: "Ages 2 to 18", languageOfInstruction: "English" },
  { name: "Trinity International School", slug: "trinity-international-school", curricula: ["American", "Adventist"], budget: "under400k", website: "https://trinity.ac.th", description: "Trinity is a Christian, student-centered school licensed by Thailand's Ministry of Education and a member of the International Schools Association of Thailand, positioning it within the country's broader network of ISAT-affiliated international schools rather than operating in isolation.\n\nThe school combines academic study with a stated focus on character development, meaning its program is built around more than just exam results, with explicit attention to values and personal growth as part of the regular curriculum rather than a separate co-curricular track.\n\nAs a Christian school, Trinity shares some similarities in mission with ICS, Bangkok Christian International, and Ekamai, though each of these faith-based schools has its own specific denominational background, campus culture, and curriculum details that families researching this category of school should compare individually.\n\nFamilies drawn to Trinity are generally specifically seeking that combination of Ministry of Education licensing, ISAT membership, and an explicit character-development focus alongside standard academics.", ageRange: "Kindergarten to Grade 12", languageOfInstruction: "English" },
  { name: "Verso International School", slug: "verso-international-school", curricula: ["American"], budget: "over400k", description: "VERSO International School closed in 2026. Its campus near Suvarnabhumi Airport has reopened as Wycombe Abbey International School Bangkok, listed separately in this directory." },
  { name: "Wellington International School Bangkok", slug: "wellington-international-school-bangkok", curricula: ["British"], budget: "over400k", website: "https://www.wellingtoncollege.ac.th", founded: 2018, description: "Wellington Bangkok is affiliated with Wellington College in the UK, joining Harrow, Shrewsbury, and Brighton College as part of a cluster of UK-linked British schools that have opened in Bangkok since the early 2000s, each bringing a version of their home institution's pastoral system and house structure into a Thai campus.\n\nThe school follows the English National Curriculum through to IGCSE and A-Levels, and places a specific emphasis on wellbeing as a stated part of its educational philosophy, which is a hallmark Wellington College brings across its international network, not just a Bangkok-specific initiative.\n\nAs one of the more recently established UK-affiliated schools in the city, Wellington has built modern, purpose-designed facilities from the outset rather than expanding an older campus incrementally, which shows in its sports and arts spaces.\n\nFamilies weighing Wellington against Bangkok's other UK-affiliated schools are typically comparing similar academic outcomes, since all follow the same underlying English curriculum and exam boards, with the real differences coming down to campus location, facilities, and the specific culture each home UK institution brings to its house system.", ageRange: "Ages 2 to 18", languageOfInstruction: "English", feeRange: "615,250 to 1,240,137 THB/year" },
  { name: "Shrewsbury International School Bangkok", slug: "shrewsbury-international-school-bangkok", curricula: ["British"], budget: "over400k", description: "Shrewsbury Bangkok carries a genuine, direct affiliation with the 500 year old Shrewsbury School in the UK, rather than just borrowing the name, which means its curriculum, pastoral structure, and house system are modeled closely on the original English boarding school rather than built from scratch for the Bangkok market.\n\nThe school operates two campuses, a riverside site and a second City Campus in Huai Khwang, giving it more flexibility on location than most single-campus Bangkok schools. Families choosing between the two generally weigh commute against campus facilities, since the original riverside site has more space for sports and outdoor activities.\n\nAcademically, Shrewsbury follows the English National Curriculum through IGCSE, then A-Levels rather than the IB, which is a meaningful distinction from several of its British-curriculum peers in the city. It has built a reputation as one of the more academically competitive British schools in Bangkok, with strong university placement outcomes.\n\nFounded in 2003, Shrewsbury is younger than Patana or ISB, but has grown quickly on the strength of its UK affiliation and has become one of the established names families compare against Patana when weighing British curriculum options in the city.", website: "https://www.shrewsbury.ac.th", founded: 2003, ageRange: "Ages 2 to 18", languageOfInstruction: "English", feeRange: "691,800 to 1,208,400 THB/year" },
  { name: "International School Bangkok (ISB)", slug: "international-school-bangkok-isb", curricula: ["American", "International Baccalaureate"], budget: "over400k", description: "ISB holds the distinction of being Thailand's first international school, opening in 1951 as the International Children's Center on the grounds of the US Embassy, serving an initial group of just 50 children from UN and embassy families. That history helps explain why the school still carries an unusually international, diplomatic-community feel even today.\n\nThe campus occupies roughly 37 acres inside Nichada Thani, a gated residential community in Nonthaburi built specifically around the school. Many ISB families choose to live inside or near Nichada Thani itself, since it removes the cross-town commute that affects families at more centrally located schools, at the cost of being further from downtown Bangkok on weekends.\n\nAcademically, ISB runs an American curriculum through Advanced Placement courses, with the IB Diploma Programme also available as an option in the final two years, giving families a choice between the two most internationally recognized university pathways. ISB was the first school in Thailand to offer the IB Diploma at all, alongside its American track.\n\nWith around 1,900 students, ISB is large enough to field a full IASAS athletics and arts program, and its extensive campus includes facilities that go well beyond a typical school day, more in line with a small American high school and college campus combined.", website: "https://www.isb.ac.th", founded: 1951, ageRange: "Ages 3 to 18", languageOfInstruction: "English", feeRange: "681,000 to 1,219,000 THB/year" },
  { name: "Ruamrudee International School (RIS)", slug: "ruamrudee-international-school-ris", curricula: ["American", "International Baccalaureate"], budget: "over400k", website: "https://www.rism.ac.th", founded: 1957, description: "Ruamrudee, almost always referred to as RIS, is one of Bangkok's oldest American curriculum schools, founded the same year as Bangkok Patana in 1957, and has grown into one of the largest international schools in the city by enrollment. It offers a genuinely broad range of pathways, including an American diploma track, AP courses, and the IB Diploma Programme as an option in the final two years.\n\nThe main campus is large enough to support both a full American-style athletics and activities program and a separate Swiss Section teaching a German-language curriculum for German-speaking families, an unusual combination that reflects how large and diverse the school's population has become over nearly seven decades.\n\nRIS is a member of IASAS, competing directly against ISB, Patana, NIST, and other major regional schools in sports and arts, which places it firmly among Bangkok's tier of large, well-resourced international schools rather than the city's smaller boutique options.\n\nWith such long history and scale, RIS tends to appeal to families who want an established, full-service American school with genuine choice in exam pathway, rather than a smaller or more specialized option.", ageRange: "Ages 2 to 18", languageOfInstruction: "English", feeRange: "548,400 to 1,527,000 THB/year" },
  { name: "King's College International School Bangkok", slug: "kings-college-international-school-bangkok", curricula: ["British"], budget: "over400k", website: "https://www.kingsbangkok.ac.th", founded: 2020, description: "King's College Bangkok is affiliated with King's College School in Wimbledon, UK, joining the cluster of UK-linked British schools that have opened in Bangkok over the past two decades alongside Harrow, Shrewsbury, Brighton College, and Wellington. It follows the English National Curriculum through IGCSE and A-Levels.\n\nOpened in 2020, King's College Bangkok is one of the newest of these UK-affiliated schools in the city, which means its facilities were purpose designed from the outset rather than expanded incrementally from an older site, though it also means the school has a shorter local track record than its more established peers.\n\nAs with the other UK-affiliated schools in Bangkok, King's leans on its direct institutional link to the UK original for curriculum planning, teacher training, and pastoral structure, giving Bangkok families a way to access that specific UK school's approach without leaving Thailand.\n\nFamilies comparing King's College against Bangkok's other recently opened UK-affiliated schools are typically weighing similar factors: campus location, facilities, and which UK institution's specific culture and house system appeals to them, since the underlying English curriculum is broadly consistent across this group of schools.", ageRange: "Ages 2 to 18", languageOfInstruction: "English", feeRange: "616,000 to 1,063,000 THB/year" },
    { name: "St Andrews International School Bangkok", slug: "st-andrews-international-school-bangkok", curricula: ["British", "International Baccalaureate"], budget: "over400k", website: "https://www.nordangliaeducation.com/sta-bangkok", founded: 1997, description: "This is the original St Andrews campus in Bangkok, located in the Vadhana district and owned by Nord Anglia Education, a major international schools group that also owns schools across Asia, Europe, and the Americas. It is a separate operation from the unrelated Cognita-owned St Andrews campuses at Sathorn, Sukhumvit 107, and Dusit, despite the shared name.\n\nFounded in 1997, the school offers a British-style education from Foundation Stage age 2 through to age 18, and being part of the Nord Anglia network gives it access to shared curriculum resources and partnerships across that group's other schools worldwide, including collaborations with organizations like MIT and Juilliard that Nord Anglia arranges centrally.\n\nThe school has picked up IB and international school awards recognition in past years, and being commonly known by the abbreviation STA71, referencing its location on Sukhumvit Soi 71, helps distinguish it locally from the other St Andrews branded campuses in the city that operate under entirely different ownership.\n\nFamilies should be careful not to confuse this school with the Cognita-run St Andrews campuses elsewhere in Bangkok. Despite the identical branding, they are unrelated schools under separate ownership groups with their own curricula and admissions.", ageRange: "Ages 2 to 18", languageOfInstruction: "English", feeRange: "400,700 to 873,800 THB/year", photo: "/images/schools/st-andrews-international-school-bangkok.jpg" },
  { name: "Wells International School", slug: "wells-international-school", curricula: ["American", "International Baccalaureate"], budget: "over400k", website: "https://wells.ac.th", founded: 1999, description: "Founded in 1999, Wells has grown to four campuses across Bangkok and one in Chonburi, following a combined American and IB curriculum. The school is known for relatively small average class sizes, around 16 students, and a close student-to-teacher ratio.", ageRange: "Kindergarten to Grade 12", languageOfInstruction: "English" },
  { name: "Regent's International School Bangkok", slug: "regents-international-school-bangkok", curricula: ["British", "International Baccalaureate"], budget: "over400k", website: "https://regents.ac.th", description: "Regent's International School Bangkok teaches the English National Curriculum from Early Years through IGCSE, then offers the IB Diploma Programme in the Sixth Form rather than A-Levels, a similar structural choice to Bangkok Patana. That combination of British curriculum through IGCSE with an IB finish is less common among Bangkok's British schools, most of which stick with A-Levels straight through.\n\nThe school is a member of the Round Square Association, an international network of schools built around service, adventure, and experiential learning alongside academics, which shapes its co-curricular program more than pure exam preparation does at some other British schools in the city.\n\nRegent's has also built specific outside partnerships into its program, including a Premier League football academy collaboration and a partnership with Yamaha Music School, giving students structured access to specialist coaching in sport and music beyond what an in-house PE or music department would typically offer.\n\nAs one of Bangkok's longer established British schools, Regent's competes for families alongside Patana and the city's other major British curriculum options, with its Round Square membership and specific external partnerships forming part of what differentiates it from its peers.", ageRange: "Ages 2 to 18", languageOfInstruction: "English" },
  { name: "Amnuay Silpa School", slug: "amnuay-silpa-school", curricula: ["British", "Thai"], budget: "over400k", website: "https://www.amnuaysilpa.ac.th", founded: 1926, description: "Amnuay Silpa runs a genuinely dual curriculum rather than an English-medium school with Thai bolted on. In the younger years, students learn simultaneously in Thai and English within the same classroom, taught side by side by native speaker teachers in each language. Moving into secondary school, subjects like maths, science, and history split into parallel Thai-language and English-language classes that are deliberately coordinated to reinforce one another, letting students work toward both Thai national exams and the IGCSE and A-Level track.\n\nThe school also brands itself around a Thinking School framework, developed in partnership with Exeter University, aimed at building critical and reflective thinking into everyday lessons rather than teaching purely to the test. That approach earned ANS Advanced Thinking School accreditation, membership in FOBISIA, and full CIS accreditation, making it the first bilingual school in Thailand to hold CIS status.\n\nThe central Bangkok campus, a short walk from Phaya Thai BTS station, has separate purpose built buildings for its Foundation, Primary, and Secondary phases, along with a 25 meter pool, a dedicated ballet studio, science labs, and a large football pitch at the heart of the site. Outside the regular timetable, the school runs one of the more extensive after school programs in the city, with more than 100 clubs spanning sports, robotics, performing arts, and language options including Mandarin and Japanese.\n\nEntry into the youngest year groups is largely first come, first served, while places from Year 1 onward are assessed through testing, an interview, and reports from the student\'s previous school. Given the school\'s reputation, popular year groups often carry a waiting list, founded in 1926, Amnuay Silpa counts six former Thai prime ministers among its alumni.", ageRange: "Ages 2 to 18", languageOfInstruction: "English, Thai", photo: "/images/schools/amnuay-silpa-school.jpg" },
  { name: "Invictus International Programme", slug: "invictus-international-programme", curricula: ["British"], budget: "over400k", website: "https://www.invictus.school", description: "The Thailand branch of Invictus International School, a network founded in Singapore in 2015 that positions itself as an affordable pathway into Cambridge-curriculum international education, spanning Years 1 to 13.", languageOfInstruction: "English" },
  { name: "RBIS International School", slug: "rbis-international-school", curricula: ["British"], budget: "over400k", website: "https://rbis.ac.th", description: "A British-curriculum school offering the English National Curriculum from Early Years through IGCSE and post-16 pathways including A-Levels or BTEC. RBIS keeps class sizes small, with Nursery capped at 12 students, and runs a dedicated English as an Additional Language program.", languageOfInstruction: "English" },
  { name: "Singapore International School of Bangkok", slug: "singapore-international-school-of-bangkok", curricula: ["British", "International Baccalaureate", "Singaporean"], budget: "over400k", website: "https://www.sisb.ac.th", founded: 2001, description: "The flagship campus of SISB (Singapore International School), the only education group listed on the Stock Exchange of Thailand. Founded in 2001, SISB Pracha Uthit teaches a combined Singapore and UK curriculum trilingually in English, Chinese, and Thai, one of six SISB campuses across the country.", ageRange: "Nursery to Year 13", languageOfInstruction: "English, Chinese, Thai" },
  { name: "Norwich International School", slug: "norwich-international-school", curricula: ["International Baccalaureate", "British"], budget: "over400k", website: "https://www.norwichschool.ac.th", founded: 2014, description: "Founded in 2014 in southwest Bangkok near Samut Sakhon, Norwich follows the British National Curriculum from EYFS through IGCSE, with the IB Diploma Programme offered in the final two years, and introduces Mandarin from Nursery.", ageRange: "Ages 2 to 18", languageOfInstruction: "English" },
  { name: "Sequoia Nova International Primary School", slug: "sequoia-nova-international-primary-school", curricula: ["French"], budget: "under400k", website: "https://sequoia-nova.com", founded: 2025, description: "Opened in September 2025 in Sathorn as a joint venture between Acacia Education Group and WeLearn Academy, Sequoia Nova serves only ages 6 to 11 across two tracks: an English-medium section aligned with US Common Core standards, and a French Bilingual section following the French national curriculum.", ageRange: "Ages 6 to 11", languageOfInstruction: "English, French" },
  { name: "Rose Marie Academy", slug: "rose-marie-academy", curricula: ["American"], budget: "over400k", website: "https://rose-marie.ac.th", description: "A small American-curriculum school based in Nonthaburi, serving families outside central Bangkok with a lower public profile than the city's larger international schools.", languageOfInstruction: "English" },
  { name: "XCL American School of Bangkok", slug: "xcl-american-school-of-bangkok", curricula: ["American"], budget: "over400k", website: "https://www.asbsk.ac.th", founded: 1983, description: "Originally opened in 1983 as Didyasarin International Kindergarten, this Sukhumvit campus operated for decades as part of the American School of Bangkok before being acquired by XCL Education in 2022 and rebranded XCL American School of Bangkok, teaching an AP-integrated American curriculum near Thong Lo.", languageOfInstruction: "English" },
  { name: "Thai-Singapore International School", slug: "thai-singapore-international-school", curricula: ["British", "Singaporean"], budget: "unknown", description: "A smaller Bangkok school combining British and Singaporean curriculum elements, part of the city's broader network of Singapore-style education providers.", languageOfInstruction: "English" },
  { name: "Bangkok Adventist International School", slug: "bangkok-adventist-international-school", curricula: ["American", "Adventist"], budget: "unknown", website: "https://bais.ac.th", description: "A Seventh-day Adventist school offering an American curriculum, part of the Adventist education network that also operates Ekamai International School in Bangkok.", languageOfInstruction: "English" },
  { name: "Rising Oaks International School Bangkok", slug: "rising-oaks-international-school-bangkok", curricula: ["British"], budget: "under400k", website: "https://roisb.ac.th", founded: 2006, description: "Established in 2006, Rising Oaks follows the National British Curriculum from Nursery through Year 11, with average class sizes of 20 to 25 students and a full calendar of school events including Songkran and international celebrations.", ageRange: "Nursery to Year 11", languageOfInstruction: "English" },
  { name: "Astra Academy International School", slug: "astra-academy-international-school", curricula: ["British"], budget: "over400k", website: "https://www.astra.ac.th", description: "A UK-curriculum school in Bangkok's Ekkamai neighborhood built around a future-focused, student-centered approach, with facilities including an eco garden, cooking classroom, and swimming pool.", languageOfInstruction: "English" },
  { name: "WeLearn Academy", slug: "welearn-academy", curricula: ["American", "British", "Thai"], budget: "under400k", website: "https://welearnthailand.com", description: "Founded by educator David Doran as a project-based alternative to traditional schooling, WeLearn focuses on entrepreneurship, real-world skills, and learner-driven education rather than a conventional curriculum structure, and is also the co-founder behind the newer Sequoia Nova primary school.", languageOfInstruction: "English, Thai" },
  { name: "St. Mark's International School", slug: "st-marks-international-school", curricula: ["Australian", "Singaporean"], budget: "unknown", website: "https://stmarks.ac.th", founded: 1999, description: "Established in 1999 as the first Australian international school in Thailand, St. Mark's is a Christian school in the Suan Luang district teaching an Australian and Singapore curriculum at primary level, moving to IGCSE and A-Levels in secondary.", languageOfInstruction: "English" },
  { name: "Australian International School Bangkok", slug: "australian-international-school-bangkok", curricula: ["British", "Australian"], budget: "over400k", website: "https://www.australianisb.ac.th", founded: 2002, description: "AISB was founded in 2002, originally registered under the name Aucksara International School before adopting its current Australian-branded identity. It sits in the Sukhumvit area and serves a genuinely broad international community, with students representing more than 40 nationalities.\n\nThe school follows an Australian and British-influenced curriculum blend rather than a single national curriculum framework, which is a somewhat distinctive academic positioning compared to the more standard British or American curriculum choices most other Bangkok international schools offer.\n\nAs a mid-sized school in a well-connected Sukhumvit location, AISB tends to appeal to families who want an established international curriculum without the scale of the city's largest schools, and who are specifically interested in an Australian-influenced educational approach.\n\nWith over two decades of operating history now, AISB has moved well past its early years as Aucksara International School and built its own identity and reputation under the Australian International School branding it has carried for most of its history.", languageOfInstruction: "English" },
  { name: "International Christian School Nonthaburi", slug: "international-christian-school-nonthaburi", curricula: ["American", "Christian"], budget: "over400k", website: "https://icsn.ac.th", description: "A Christian, American-curriculum school located in Nonthaburi, just outside central Bangkok, serving families in the northern greater Bangkok area.", languageOfInstruction: "English" },
  { name: "Beaconhouse Yamsaard International School", slug: "beaconhouse-yamsaard-international-school", curricula: ["British"], budget: "under400k", website: "https://bys.ac.th", description: "Part of the Beaconhouse School System, a global network with over 1,000 schools originating in Pakistan, Beaconhouse Yamsaard operates multiple campuses across Thailand including Ladprao, Rangsit, Hua Hin, and Pattanakarn, serving more than 3,800 students in total.", languageOfInstruction: "English, Thai" },
  { name: "BSB British International Primary School", slug: "bsb-british-international-primary-school", curricula: ["British"], budget: "over400k", website: "https://bsbangkok.ac", founded: 1992, description: "Founded in March 1992 on Sukhumvit Soi 4, BSB is a primary-only school (EYFS through Year 6) with a deliberately close-knit community of around 180 students from over 40 nationalities, and a notably low teacher-to-student ratio in Nursery.", ageRange: "Ages 2 to 11", languageOfInstruction: "English" },
  { name: "Crescent International School", slug: "crescent-international-school", curricula: ["British"], budget: "unknown", website: "https://cis.ac.th", founded: 2008, description: "Established in 2008 in the heart of Sathorn, Crescent is one of the only schools in Thailand offering Arabic, Thai, and Islamic Studies up to IGCSE level alongside a strong maths and science focus, following the National Curriculum for England.", languageOfInstruction: "English" },
  { name: "Royce Royal International School", slug: "royce-royal-international-school", curricula: ["British"], budget: "under400k", website: "https://www.royceroyal.ac.th", description: "A British-curriculum school serving Bangkok families, part of the city's broader range of mid-sized international school options.", languageOfInstruction: "English" },
  { name: "Dulwich College International School Bangkok", slug: "dulwich-college-international-school-bangkok", curricula: ["British"], budget: "over400k", website: "https://bangkok.dulwich.org", founded: 2026, description: "Dulwich College International School Bangkok is the newest addition to Bangkok's international school market, opening in August 2026 in the Bang Na district as the first Dulwich College International campus in Thailand. The physical campus was designed around a traditional Thai village-style layout rather than a standard international school building template.\n\nAcademically, it follows the English National Curriculum through IGCSE, then gives students a choice between the IB Diploma Programme and A-Levels in the final two years, a structural flexibility that puts it in a similar category to Regent's and Bangkok Patana in offering an IB option alongside a British foundation.\n\nThe school is part of the global Dulwich College International network, which itself traces its roots to Dulwich College London, founded in 1619, giving the Bangkok campus access to a long institutional lineage and a network of sister campuses across Asia even though the Bangkok site itself just opened.\n\nGiven how recently Dulwich Bangkok opened, it does not yet have local exam results or an established reputation the way Bangkok's longer running schools do. Families considering it are weighing the appeal of a well-resourced new campus and strong global network against the lack of a proven local track record.", ageRange: "Ages 3 to 18 (opening with Nursery to Year 6, expanding through 2029)", languageOfInstruction: "English" },
  { name: "Thai-Chinese International School", slug: "thai-chinese-international-school", curricula: ["American"], budget: "over400k", website: "https://www.tcis.ac.th", description: "A member of the Bangkok International Schools Athletic Conference (BISAC), Thai-Chinese International School fields teams across football, basketball, volleyball, golf, swimming, and other sports as part of its American curriculum program.", languageOfInstruction: "English, Chinese" },
  { name: "Kids Academy International School", slug: "kids-academy-international-school", curricula: ["British", "Chinese", "Japanese"], budget: "unknown", website: "https://www.kidsacademy.ac.th", description: "A smaller international pre-school in Bangkok offering British curriculum foundations alongside Chinese and Japanese language exposure.", languageOfInstruction: "English" },
  { name: "Ramkhamhaeng Advent International School", slug: "ramkhamhaeng-advent-international-school", curricula: ["Adventist", "American"], budget: "under400k", website: "https://www.rais.ac.th", founded: 1999, description: "Founded in 1999 by Mr. Udom Srikureja, RAIS is a Seventh-day Adventist school in Bang Kapi following a structured American curriculum, serving around 700 students with sports including basketball, swimming, and badminton.", languageOfInstruction: "English" },
  { name: "Pan-Asia International School", slug: "pan-asia-international-school", curricula: ["International Baccalaureate", "American"], budget: "unknown", website: "http://www.pais.ac.th", founded: 2004, description: "Located in the Prawet district about 10km from Suvarnabhumi Airport, PAIS follows American academic standards with a deliberate emphasis on Eastern culture, serving students from more than 40 nations.", languageOfInstruction: "English" },
  { name: "NIVA American International School", slug: "niva-american-international-school", curricula: ["American", "Christian"], budget: "over400k", website: "https://www.niva.ac.th", founded: 1991, description: "NIVA was founded in 1991 in the Bang Kapi area, and the school's name comes directly from the founders' own children, Nicholas and Vanisara, giving it a genuinely family-founded origin story similar to Charter International School. It follows a North American curriculum with AP course offerings available in high school.\n\nThe school marked its 30th anniversary in 2021, giving it more than three decades of local operating history, a meaningful track record for a family-founded American curriculum school of its size.\n\nAs a family-founded rather than corporately owned or internationally networked school, NIVA has more independence in shaping its specific culture and priorities, similar in structure to Charter or KPIS, though with a North American rather than British curriculum focus.\n\nFamilies choosing NIVA over Bangkok's larger American schools like ISB or Berkeley are typically looking for a smaller, more established family-run alternative with a genuine multi-decade history in the same Bang Kapi location.", ageRange: "Ages 3 to 18", languageOfInstruction: "English" },
  { name: "John Wyatt Montessori Bangkok", slug: "john-wyatt-montessori-bangkok", curricula: ["American", "Montessori"], budget: "unknown", website: "https://www.jwmontessori.com", description: "An American-curriculum school built around Montessori teaching principles, offering child-led early learning in Bangkok.", languageOfInstruction: "English" },
  { name: "SPGS International School Bangkok", slug: "spgs-international-school-bangkok", curricula: ["British"], budget: "over400k", founded: 2026, description: "A newer addition to Bangkok's British-curriculum school options, opening in 2026.", languageOfInstruction: "English" },
  { name: "New Day Learning", slug: "new-day-learning", curricula: ["Special Educational Needs"], budget: "unknown", website: "https://newdaylearningco.com", description: "A Bangkok school specializing in education for students with special educational needs, distinct from the city's mainstream international school options.", languageOfInstruction: "English" },
  { name: "British Mandarin International School", slug: "british-mandarin-international-school", curricula: ["British", "Chinese"], budget: "over400k", website: "https://bmis.ac.th", description: "A British-curriculum school in Bangkok with a dedicated Mandarin Chinese language program woven into daily instruction, aimed at families wanting a bilingual British-style education.", languageOfInstruction: "English, Chinese" },
  { name: "Lertlah School", slug: "lertlah-school", curricula: ["Canadian"], budget: "unknown", website: "https://lertlah.com", description: "A Bangkok school following the Canadian curriculum, offering families an alternative to the more common British and American curriculum options in the city.", languageOfInstruction: "English" },
  { name: "St. Andrews International School Sathorn", slug: "st-andrews-international-school-sathorn", curricula: ["British"], budget: "over400k", website: "https://www.standrewssathorn.com", founded: 2003, description: "Opened in January 2003 in a renovated former hospital building near Silom, St. Andrews Sathorn is a primary-only campus within the four-school St. Andrews network in Thailand, part of the global Cognita group. Students typically continue to the Sukhumvit 107 campus for secondary school.", ageRange: "Ages 2 to 11 (Nursery to Year 6)", languageOfInstruction: "English" },
  { name: "Westminster College Bangkok", slug: "westminster-college-bangkok", curricula: ["American", "British"], budget: "unknown", website: "https://westminster.ac.th", description: "A Bangkok school blending American and British curriculum elements, part of the city's wider mix of combined-curriculum international schools.", languageOfInstruction: "English" },
  { name: "Modern International School Bangkok", slug: "modern-international-school-bangkok", curricula: ["British"], budget: "under400k", website: "https://www.misb.ac.th", founded: 1997, description: "Established in 1997 on Sukhumvit Soi 39, MISB follows the National British Curriculum from Nursery through Year 13, offering IGCSE and A-Level examinations, and is an accredited Cambridge International Examinations center.", ageRange: "Nursery to Year 13", languageOfInstruction: "English" },
  { name: "Thai International School", slug: "thai-international-school", curricula: ["American"], budget: "over400k", website: "https://thaiinternationalschool.ac.th", description: "A WASC-accredited American curriculum school on a 30-rai riverside campus in Pathum Thani, currently serving Nursery through Grade 6 with an emphasis on preserving Thai manners and customs alongside international academics.", ageRange: "Nursery to Grade 6", languageOfInstruction: "English" },
  { name: "Satit Pattana Secondary School", slug: "satit-pattana-secondary-school", curricula: ["British"], budget: "unknown", website: "https://www.satitpattana.ac.th", description: "A British-curriculum secondary school in Bangkok, part of the city's Satit (demonstration school) network affiliated with Thai universities.", languageOfInstruction: "English" },
  { name: "Kincaid International School of Bangkok", slug: "kincaid-international-school-of-bangkok", curricula: ["International Baccalaureate"], budget: "under400k", website: "https://www.kincaidbangkok.com", description: "An IB-curriculum school in Bangkok offering the International Baccalaureate framework as its core academic program.", languageOfInstruction: "English" },
  { name: "Siam International School", slug: "siam-international-school", curricula: ["British"], budget: "over400k", website: "https://www.siamis.ac.th", description: "Located on a 40-rai campus in Thanyaburi, Pathum Thani, Siam International School is authorized by Thailand's Ministry of Education from kindergarten through Grade 6, with a curriculum emphasis on self-development.", ageRange: "Kindergarten to Grade 6", languageOfInstruction: "English" },
  { name: "Wycombe Abbey International School Bangkok", slug: "wycombe-abbey-international-school-bangkok", curricula: ["British"], budget: "over400k", website: "https://wycombeabbey.ac.th", founded: 2026, description: "Wycombe Abbey International School Bangkok opened in August 2026 on the former VERSO International School campus near Suvarnabhumi Airport, making it one of the newest entrants into Bangkok's British school market. It is affiliated with Wycombe Abbey in the UK, a school with roots going back to 1896, giving the Bangkok campus a genuine historical lineage despite being brand new locally.\n\nThe school follows a British curriculum through IGCSE and A-Levels, and notably offers a full boarding program alongside day places, which is relatively unusual among Bangkok's international schools and puts it in the same small group as Harrow in offering that option.\n\nBecause the campus is inherited from VERSO rather than purpose built from scratch, families researching Wycombe Abbey Bangkok should expect a transition period as the new operator establishes its own systems, culture, and track record on a site with an existing physical footprint but a completely new institutional identity.\n\nGiven how recently it opened, Wycombe Abbey does not yet have a local exam results history or established reputation the way Bangkok's longer running UK-affiliated schools do, which is worth factoring in for families prioritizing a proven track record over the appeal of joining at the ground floor of a new school.", languageOfInstruction: "English" },
  { name: "St. Andrews International School Dusit", slug: "st-andrews-international-school-dusit", curricula: ["British"], budget: "over400k", website: "https://www.standrewsdusit.com", description: "A primary-only campus in the Dusit area, part of the four-school St. Andrews network in Thailand under the Cognita group, offering the English National Curriculum to children aged 2 to 11 before they typically move on to secondary school at another St. Andrews campus.", ageRange: "Ages 2 to 11 (Nursery to Year 6)", languageOfInstruction: "English" },
  { name: "Siam Singapore International School", slug: "siam-singapore-international-school", curricula: ["British", "Singaporean"], budget: "unknown", description: "A Bangkok school combining British and Singaporean curriculum elements, part of the city's network of Singapore-style education providers.", languageOfInstruction: "English" },
  { name: "Aster International School Bangkok", slug: "aster-international-school-bangkok", curricula: ["British"], budget: "over400k", website: "https://aster.ac.th", description: "A newer addition to Bangkok's school scene, built on a purpose-built campus in the city center. Aster combines an enhanced British international curriculum with project- and theme-based learning, giving younger students an open-ended, learning-without-limits approach before moving into a more structured primary program.", languageOfInstruction: "English" },
  { name: "RIS Swiss Section Deutschsprachige Schule Bangkok", slug: "ris-swiss-section-deutschsprachige-schule-bangkok", curricula: ["Swiss", "International", "German"], budget: "over400k", website: "https://ris-swiss-section.org", description: "A German-language section operating within the Ruamrudee International School (RIS) system, offering a Swiss-German curriculum pathway for German-speaking families in Bangkok.", languageOfInstruction: "German, English" },
  { name: "Lycée Français International de Bangkok", slug: "lycee-francais-international-de-bangkok", curricula: ["French"], budget: "over400k", website: "http://www.lfib.ac.th", description: "A French curriculum school in the Wang Thonglang district teaching elementary through high school levels, following the French national education system with English and Thai also taught as part of the program.", languageOfInstruction: "French, English, Thai" },
  { name: "TSI International School", slug: "tsi-international-school", curricula: ["British"], budget: "under400k", website: "https://tsi.ac.th", founded: 1985, description: "Formerly known as Thai Sikh International School, TSI has operated since 1985 and now runs two campuses, including its main Bearing site near Bearing BTS station in Samut Prakan, serving students from Pre-Nursery through Year 13.", languageOfInstruction: "English" },
  { name: "Future Steps International School Bangkok", slug: "future-steps-international-school-bangkok", curricula: ["British"], budget: "over400k", website: "https://thefirststeps.ac.th", description: "A British-curriculum school in Bangkok, part of the city's broad range of mid-sized international education options.", languageOfInstruction: "English" },
  { name: "King Mongkut's International Demonstration School", slug: "king-mongkuts-international-demonstration-school", curricula: ["American"], budget: "over400k", website: "https://www.kmids.ac.th", description: "Developed under King Mongkut's Institute of Technology Ladkrabang (KMITL), KMIDS is a STEAM-focused school accredited by the Western Association of Schools and Colleges, with graduates going on to universities including Chulalongkorn, Mahidol, and Keio.", languageOfInstruction: "English" },
  { name: "The Jataka School", slug: "the-jataka-school", curricula: ["British", "Buddhist"], budget: "under400k", website: "https://www.thejatakaschool.com", description: "A Bangkok school combining British curriculum academics with a Buddhist values-based approach to education.", languageOfInstruction: "English" },
  { name: "Sarasas Ektra School", slug: "sarasas-ektra-school", curricula: ["Catholic", "International", "Thai"], budget: "unknown", website: "https://www.ektra.ac.th", description: "Part of the long-running Sarasas school network in Thailand, Sarasas Ektra combines Catholic educational values with an international, bilingual Thai-English program.", languageOfInstruction: "English, Thai" },
  { name: "AIT International School", slug: "ait-international-school", curricula: ["American"], budget: "under400k", description: "An American-curriculum school in Bangkok, part of the city's wide range of US-accredited school options.", languageOfInstruction: "English", photo: "/images/schools/ait-international-school.jpg" },
  { name: "St. Andrews Samakee International School", slug: "st-andrews-samakee-international-school", curricula: ["British"], budget: "over400k", website: "https://www.standrews-samakee.com", description: "A British-curriculum school in Bangkok, part of the city's range of St. Andrews-branded and British-style education providers.", languageOfInstruction: "English" },
  { name: "St. Andrews International School Sukhumvit 107", slug: "st-andrews-international-school-sukhumvit-107", curricula: ["British", "International Baccalaureate"], budget: "over400k", website: "https://www.standrewssukhumvit.com", founded: 1996, description: "Established in 1996 near Bearing BTS station in Bang Na, this is the only one of Bangkok's three St. Andrews Cognita campuses to offer both primary and secondary education, combining the English National Curriculum with the IB Diploma Programme in the senior years.", ageRange: "Ages 2 to 18", languageOfInstruction: "English" },
  { name: "Knightsbridge House International School Nonthaburi", slug: "knightsbridge-house-international-school-nonthaburi", curricula: ["British"], budget: "under400k", website: "https://kbh.ac.th", description: "A British-curriculum school located in Nonthaburi, just outside central Bangkok, serving families in the northern greater Bangkok area.", languageOfInstruction: "English" },
  { name: "Raffles American School Bangkok", slug: "raffles-american-school-bangkok", curricula: ["American"], budget: "under400k", website: "https://ras.ac.th", founded: 2012, description: "Located in Samut Prakan just outside Bangkok's city limits, Raffles American School is part of the Raffles Education Group network, offering a US-accredited curriculum from Pre-K through Grade 12 with a US high school diploma and AP course options.", ageRange: "Ages 2 to 18", languageOfInstruction: "English" },
  { name: "RC International School", slug: "rc-international-school", curricula: ["British"], budget: "under400k", website: "https://www.rcis.ac.th", description: "A British-curriculum school in Bangkok, offering families another option among the city's many National Curriculum for England providers.", languageOfInstruction: "English" },
  { name: "Roong Aroon International School", slug: "roong-aroon-international-school", curricula: ["International Baccalaureate"], budget: "over400k", website: "https://www.roongaroonis.ac.th", founded: 1997, description: "A non-profit school on a 20-acre green campus in the Bang Khun Thian district, grounded in Buddhist values and experiential, holistic learning. Roong Aroon is an IB World School offering the Middle Years Programme, built on an Australian curriculum base, and the Career-related Programme in Grades 11 and 12.", languageOfInstruction: "English, Thai" },
  { name: "Satit Bilingual School of Rangsit University", slug: "satit-bilingual-school-of-rangsit-university", curricula: ["British", "International Baccalaureate"], budget: "under400k", website: "https://sbs.ac.th", description: "Located in Pathum Thani, SBS Rangsit combines the IB Primary Years Programme with Cambridge IGCSE and A-Levels in the secondary years, teaching bilingually in Thai and English with Chinese offered as an additional language. Students can earn pre-university credit toward top Thai and international universities.", ageRange: "Ages 2 to 18", languageOfInstruction: "English, Thai" },
  { name: "Montessori Academy Bangkok International School", slug: "montessori-academy-bangkok-international-school", curricula: ["American", "Montessori"], budget: "over400k", website: "https://www.montessoribkk.com", description: "An American-curriculum school built around Montessori teaching methods, blending child-led learning with structured academic progression.", languageOfInstruction: "English" },
  { name: "Pensmith School", slug: "pensmith-school", curricula: ["British"], budget: "unknown", website: "https://pensmithschool.com", description: "A British-curriculum school in Bangkok, part of the city's broad mix of smaller National Curriculum for England providers.", languageOfInstruction: "English" },
  { name: "Bangkok-Chicago Christian International School", slug: "bangkok-chicago-christian-international-school", curricula: ["American", "Christian"], budget: "unknown", website: "https://bcci.ac.th", description: "A Christian, American-curriculum school in Bangkok, combining faith-based values with a US-style academic program.", languageOfInstruction: "English" },
];

export const ALL_CURRICULA = Array.from(
  new Set(SCHOOLS.flatMap((s) => s.curricula))
).sort();
